files.classify.ail:
module classify;
import rules;
import types;

fn classify_one(request: types.LabelRequest) -> types.Label {
  if rules.is_blank(request) {
    types.Label::Empty
  } else {
    if rules.is_illegal(request) {
      types.Label::Illegal(request.raw)
    } else {
      types.Label::Accepted(request.raw)
    }
  }
}

files.report.ail:
module report;
import types;

fn note_for(label: types.Label) -> Text {
  match label {
    types.Label::Accepted(value) => {
      value
    },
    types.Label::Empty => {
      "empty"
    },
    types.Label::Illegal(reason) => {
      "illegal"
    },
  }
}

fn report_one(label: types.Label) -> types.LabelReport {
  types.LabelReport { label: label, note: note_for(label) }
}

fn report_batch(labels: List<types.Label, 8>) -> List<types.LabelReport, 8> {
  map label in labels {
    report_one(label)
  }
}

